    "clinicalCase": "Um homem de 53 anos foi submetido à laparotomia de emergência devido à diverticulite perfurada e, em seu caso, realizadas sigmoidectomia com colostomia a Hartmann, há 7 dias. Desde o segundo dia de pós-operatório, o paciente apresenta febre intermitente de 39 °C e não consegue se alimentar em razão de distensão abdominal persistente. Ele não apresenta outras queixas. Ao exame físico, apresenta temperatura de 38,9 °C; frequência respiratória de 22 incursões respiratórias por minuto; frequência cardíaca de 114 batimentos por minuto; pressão arterial de 110 × 70 mmHg; pele quente e úmida; pulmões com murmúrios vesiculares pouco diminuídos em bases, sem ruídos adventícios; ritmo cardíaco regular, com bulhas normofonéticas, sem sopros; abdome distendido, ruídos hidroaéreos diminuídos, hipertimpânico, doloroso à palpação profunda difusamente; ferida operatória limpa e seca, sem sinais flogísticos; colostomia com bom aspecto; e sinal de Giordano negativo. O paciente está usando ciprofloxacino e metronidazol endovenosos. Hemograma: leucócitos 21 500 mm³ (valor de referência: 4 500 a 11 000 mm³), 4% de bastões (VR: 0%). Considerando o caso apresentado, quais são, respectivamente, o diagnóstico mais provável e o(s) exame(s) mais adequado(s) para investigação neste momento?",
