    "clinicalCase": "Um homem de 43 anos procura a unidade de pronto atendimento por aumento do volume abdominal há 4 semanas, associado a edema de membros inferiores. Ele nega ingestão de bebida alcoólica. Não possui alteração do hábito intestinal ou sintomas dispépticos. Relata que, quando tinha 22 anos, sofreu um atropelamento com fratura de tíbia e recebeu 2 unidades de concentrado de hemácias, quando foi diagnosticado com hepatite por vírus C. Não possui histórico médico familiar relevante. Ao exame físico, apresenta sinais vitais normais, mucosas hipocoradas +/4+ e icterícia +/4+. Os exames do aparelho cardiovascular e respiratório estão normais. O abdome apresenta-se globoso, com ruídos hidroaéreos presentes, indolor à palpação e com sinal de Piparote e macicez móvel positivos. Presença de edema em membros inferiores; pulsos arteriais presentes bilateralmente. Uma paracentese de alívio foi realizada com a drenagem de 2 litros de liquido ascítico de aspecto amarelo citrino. A contagem de células veio com 450 leucócitos por mm3, sendo 320 polimorfonucleares. Não houve acidente de punção e o diferencial entre a albumina sérica e ascítica teve resultado de 1,3. Considerando o caso clínico apresentado, a conduta terapêutica mais adequada para tratamento dessa complicação é prescrever",
