    "clinicalCase": "Uma equipe de saúde da família tem enfrentado muitas reclamações de seus usuários — os quais são residentes de uma comunidade que fica em uma região periférica de um município de médio porte — pela dificuldade para realizar agendamento de consultas médicas e odontológicas, para colher os exames solicitados pelo médico e para conseguir os medicamentos prescritos. Isso ocorre pelas seguintes razões: a população adstrita à equipe tem mais de 4 000 pessoas cadastradas; há uma redução do número de profissionais; e há falta de medicamentos na farmácia. Em reunião de equipe, os profissionais de saúde discutem a melhor maneira de resolver essas questões. A melhor estratégia para a resolver esses problemas, com a participação da comunidade, é por meio do",
