        "isCorrect": true,
        "explanation": "O Conselho Local de Saúde é o espaço adequado para aproximar usuários e unidade de saúde, permitindo participação comunitária consultiva na discussão de problemas locais de acesso e de organização dos fluxos assistenciais."
